// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance); // not enough: we need to give c balance first
        // Actually we need to fund the contract with some Ether first, then call sudicideAnyone as owner.
        // Fuzz amount to deposit into the contract.
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.sGuardPlus___owner(); // private variable inaccessible; need to get owner another way.
        // The contract inherits sGuardPlus with private __owner and no public getter, so we cannot read the owner address.
        // We must use the constructor: __owner = msg.sender when C is deployed. setUp() deploys C, so owner = address(this).
        // So we can prank as address(this) which is the owner.
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(this).balance;
        vm.prank(address(this));
        c.sudicideAnyone();
        // After selfdestruct, address(c).balance is 0 (contract destroyed), but we can check that owner's balance increased by contractBalanceBefore.
        assertTrue(address(this).balance == ownerBalanceBefore + contractBalanceBefore);
    }
}

