pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Fund the contract with a fuzzed amount of Ether
        vm.assume(amount < address(this).balance);
        vm.deal(address(this), amount);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        uint256 contractBalBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;

        c.sudicideAnyone();

        // After selfdestruct, the contract is gone; owner's balance must reflect the received funds
        uint256 ownerBalAfter = address(this).balance;
        assertTrue(ownerBalAfter == ownerBalBefore + contractBalBefore);
    }
}

