pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance + 1 ether);
        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner")))));
        vm.assume(owner != address(0));
        // Fund contract and owner
        vm.deal(address(c), amount);
        vm.deal(owner, 1 ether);
        // Record pre-balances
        uint256 preOwnerBalance = owner.balance;
        uint256 preContractBalance = address(c).balance;
        vm.prank(owner);
        try c.sudicideAnyone() {} catch {}
        uint256 postOwnerBalance = owner.balance;
        assertTrue(postOwnerBalance == preOwnerBalance + preContractBalance);
    }
}

