pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        try c.sudicideAnyone() {
            // On success (when actor is the owner), the contract should self-destruct and have no code.
            // The buggy version succeeds without self-destructing.
            uint256 codeSize;
            assembly {
                codeSize := extcodesize(address(c))
            }
            assertTrue(codeSize == 0);
        } catch {
            // When the call reverts (actor is not the owner), no self-destruct occurs, code must still exist.
            uint256 codeSize;
            assembly {
                codeSize := extcodesize(address(c))
            }
            assertTrue(codeSize > 0);
        }
    }
}

