// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // The contract's constructor sets owner to msg.sender of setUp (this contract).
        // To test the owner call, we prank as the actual owner.
        // We deploy a fresh C in setUp, so its __owner is address(this).
        // We need to call sudicideAnyone as the owner. We do NOT need a fuzzed owner;
        // the bug manifests specifically when the owner calls it.
        // However, the problem says: "Take the deciding values as FUZZ PARAMETERS of the test function
        // ... Do NOT hard-code a primitive deciding value (an amount / id / actor)".
        // The deciding actor is the owner. The owner is a state variable set in constructor.
        // We can fuzz an address, call a transfer of ownership? No, there is no transfer ownership function.
        // The only way to satisfy "fuzz parameter" is to fuzz the caller and assume it is the owner.
        // But we don't know the owner address from within the test unless we read it (no getter).
        // Since __owner is private, we cannot read it. We can only call sudicideAnyone as different addresses
        // and see if it reverts. The reference always reverts if not owner, so it won't selfdestruct.
        // The buggy version also reverts if not owner, so no difference. The difference only occurs when called by owner.
        // Therefore, we must ensure the call is made by the owner. Since we control setUp, the owner is address(this).
        // We can fuzz an address to call as, but we must assume it is the owner to trigger the difference.
        // However, we cannot assume address(this) is the fuzzed address. We can only prank as the fuzzed address
        // and hope it is the owner? That would make the test flaky. We need a deterministic way.
        // The contract has no setter, so the owner is fixed at deployment. So the only address that can trigger the difference is the deployer.
        // The instruction: "Take the deciding values as FUZZ PARAMETERS" and "Do NOT hard-code a primitive deciding value"
        // The deciding value is the caller (owner). We can fuzz the caller, but we need to deploy a new C for each fuzz run
        // so that the owner is the fuzzed address? We can deploy C in the test function with the fuzzed address as deployer.
        // But setUp deploys C once. We can deploy a new C inside testFuzz_property with a fuzzed deployer.
        // That way the owner is the fuzzed address. Then we call sudicideAnyone as that owner.
        // This respects the rule: the fuzzed parameter is the owner, no hard-coding.
        vm.prank(owner);
        C c2 = new C(); // owner becomes the fuzzed address
        // Now call sudicideAnyone as the owner
        vm.prank(owner);
        c2.sudicideAnyone();
        // After the call, check if the contract has code
        uint256 size;
        assembly {
            size := extcodesize(c2)
        }
        // Reference: selfdestruct executed -> size == 0
        // Buggy: no-op -> size > 0
        assertTrue(size == 0);
    }
}

