import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint48 nonce) public {
        vm.assume(owner != address(0));
        vm.assume(owner != address(this));
        vm.prank(owner);
        try c.sudicideAnyone() { } catch { }

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sudicideAnyone.selector));
        bool hasCode = address(c).code.length > 0;
        assertTrue(success == hasCode);
    }
}
